import { mountDecimatorBattle } from './components/app-decimator-battle.js';
import { renderDecimatorReceipt } from './components/app-decimator-draw-overlay.js';
import { decimatorBattleFixture, selectDecimatorFixturePlayer } from './craps/fixtures/decimator-battle.js';
const { snapshot, names } = decimatorBattleFixture({ wideStacks: true });
const host = document.querySelector('#battle');
let mounted;
function mount() {
  mounted?.destroy();
  mounted = mountDecimatorBattle(snapshot, { names, viewerEntryId: snapshot.you?.entryId, onResults(detail) {
    if (detail?.fallback) { mounted.destroy(); host.replaceChildren(renderDecimatorReceipt(snapshot, names)); }
  } });
  host.replaceChildren(mounted.element);
}
document.querySelector('#restart').addEventListener('click', mount);
document.querySelector('#miss').addEventListener('click', () => {
  selectDecimatorFixturePlayer(snapshot, snapshot.battleEntries.find(row => !row.eligible).address); mount();
});
mount();
window.decimatorDemo = { snapshot, mount, names };
